/**
 * UI contracts (Tier 2 D, 2026-11-26): every pinned real answer of a /v1 route the UI reads
 * (`__fixtures__/ui_contracts.json`, generated by `tests/api_v1/test_ui_contracts.py` from the real routes, nothing
 * hand-written) goes through the UI's own parser for that route. A parser that falls back to a default (an empty id, an
 * unknown kind, a missing field) fails here, so the id/job_id and bare-hex/job-id class of bug cannot pass the tests again.
 */
import { describe, expect, it } from 'vitest';
import contracts from './__fixtures__/ui_contracts.json';
import { normalizePending } from './approvalsApi';
import { parseCapabilities } from './capabilitiesApi';
import { normalizeJob, type JobListResponse, type JobProgressResponse, type JobRunSummary } from './extractionApi';
import { normalizeLibraryStatus } from './libraryApi';
import { parseReport } from './schema/schemaApi';

type Contract = { method: string; path: string; status: number; body: unknown };
const all = contracts as Record<string, Contract>;
const body = <T,>(id: string): T => {
  const entry = all[id];
  if (!entry) throw new Error(`no pinned contract ${id}: regenerate with F2W_WRITE_FIXTURES=1`);
  return entry.body as T;
};

describe('UI contracts: the real answers read by the UI parsers', () => {
  it('jobs: a handle, a list item and a progress summary all give a non-empty id, kind and state', () => {
    const list = body<JobListResponse>('jobs.list');
    expect(list.jobs.length).toBeGreaterThan(0);
    for (const raw of list.jobs as unknown[]) {
      const job = normalizeJob(raw);
      expect(job.id).not.toBe('');
      expect(job.kind).not.toBe('');
      expect(['queued', 'running', 'paused_budget', 'paused_provider', 'awaiting_review', 'succeeded', 'failed', 'cancelled']).toContain(job.state);
      expect(job.created_at).not.toBe('');
    }
    const one = normalizeJob(body('jobs.one'));
    expect(one.id).toMatch(/^job-[0-9a-f]{24}$/);   // the real id shape (a run of the Harvester is named by it)
    const progress = body<JobProgressResponse>('jobs.progress');
    expect(progress.job_id).toBe(one.id);
    const summary = progress.summary as JobRunSummary;
    expect(summary.papers.total).toBeGreaterThan(0);
    expect(summary.recovery?.total.papers_processed).toBeGreaterThan(0);
    const relations = body<JobProgressResponse>('jobs.progress.relations').summary as JobRunSummary;
    expect(relations.counters.repair_swapped).toBe(1);
    const handle = normalizeJob(body('library.kgs.passages.start'));
    expect(handle.id).toMatch(/^job-/);
    expect(handle.kind).toBe('library_passages');
  });

  it('harvest: a run id is the job id and the candidates route answers for it', () => {
    const runs = body<{ runs: Array<{ id: string; counts: Record<string, number> }> }>('harvest.runs');
    expect(runs.runs[0].id).toMatch(/^job-[0-9a-f]{24}$/);
    expect(all['harvest.candidates'].path).toContain(runs.runs[0].id);
    const candidates = body<{ candidates: Array<{ id: string; status: string; open_url: string | null }> }>('harvest.candidates');
    expect(candidates.candidates.length).toBe(2);
    for (const c of candidates.candidates) expect(c.id).toMatch(/^[0-9a-f]{16}$/);
    expect(candidates.candidates.some(c => c.status === 'paywalled' && c.open_url?.startsWith('https://doi.org/'))).toBe(true);
    expect(body<{ candidate: { status: string } }>('harvest.dismiss').candidate.status).toBe('dismissed');
  });

  it('library: status, papers, categories, bundles, schemas and models parse without defaults', () => {
    const status = normalizeLibraryStatus(body('library.status'));
    expect(status.mounted).toBe(true);
    const papers = body<{ papers: Array<{ id: string; relpath: string; title: string | null }> }>('library.papers');
    expect(papers.papers.length).toBeGreaterThan(0);
    for (const p of papers.papers) expect(p.id).toMatch(/^[0-9a-f]{16}$/);
    const kgs = body<{ bundles: Array<{ name: string; schema: string; paper_count: number }> }>('library.kgs');
    expect(kgs.bundles.map(b => b.name).sort()).toEqual(['kg1', 'plecos']);   // recorded before the continue request
    expect(kgs.bundles.find(b => b.name === 'plecos')?.schema).toMatch(/^user\//);
    const schemas = body<{ schemas: Array<{ name: string; label: string }> }>('library.schemas');
    expect(schemas.schemas.some(s => s.name.startsWith('user/'))).toBe(true);
    const models = body<{ models: unknown[] }>('library.models');
    expect(Array.isArray(models.models)).toBe(true);
    const estimate = body<{ confirmation: unknown; estimated_cost_usd: number }>('library.estimate');
    expect(estimate.confirmation).toBeTruthy();
  });

  it('schemas: the validator report and the saved-version shapes', () => {
    const report = parseReport(body('schemas.validate'));
    expect(report?.ok).toBe(true);
    expect(report?.warnings.some(w => w.code === 'attribute_slot')).toBe(true);
    const invalid = body<{ report: unknown; reason: string }>('schemas.save.invalid');
    expect(parseReport(invalid.report)?.problems.some(p => p.code === 'name_mismatch')).toBe(true);
    const list = body<{ schemas: Array<{ name: string; versions: number[]; latest: { id: string; version: number; sha256: string } }> }>('schemas.user.list');
    expect(list.schemas[0].latest.id).toMatch(/^user\/[a-z][a-z0-9_-]*@v\d+$/);
    expect(list.schemas[0].versions).toEqual([1]);
    expect(body<{ cancelled: string }>('schemas.generate.cancel').cancelled).toBe('ui-contract');
  });

  it('capabilities and approvals parse to the shapes the shell reads', () => {
    const caps = parseCapabilities(body('capabilities'));
    expect(caps.role).toBe('local_operator');
    const pending = normalizePending(body('approvals.pending'));
    expect(pending.items.length).toBeGreaterThan(0);
    expect(pending.items[0].approve?.path).toMatch(/^v1\/publications\//);
  });

  it('typed refusals carry the reason the UI words', () => {
    expect(all['library.kgs.relations.refused'].status).toBe(422);
    expect(body<{ reason: string }>('library.kgs.relations.refused').reason).toBe('not_user_schema');
    expect(all['harvest.undo.refused'].status).toBe(409);
  });
});
